$transport->calls=[];$r=$p->report('site.example',$pc,...[...$dates,null]);check(count($transport->calls)===5&&$r['sections']['overview']['rows'][0]['values']===[11.0,23.0],'Plausible Stats API v2 five queries');check($r['sections']['pages']['rows'][0]['label']==='/home','Plausible page query stripped');check($r['sections']['events']['metrics']===['visitors','events'],'Plausible goals retain separate metric definitions');foreach($transport->calls as $c){$q=json_decode($c['body'],true);check($c['url']==='https://plausible.io/api/v2/query'&&$c['headers']['Authorization']==='Bearer private-plausible'&&$q['site_id']==='site.example'&&$q['date_range']===$dates,'Plausible authenticated query');}
