foreach(['http://stats.example.com','https://127.0.0.1','https://stats.example.com/../private','https://user@stats.example.com','https://stats.example.com?a=b','https://stats.example.com:8443'] as $url)reject(fn()=>$m->validateCredential(array_replace($mc,['endpoint'=>$url])),InvalidArgumentException::class,'unsafe endpoint rejected');reject(fn()=>$p->validateCredential(array_replace($pc,['token'=>"a\r\nb"])),InvalidArgumentException::class,'header injection rejected');$transport->status=429;try{$p->report('site.example',$pc,...[...$dates,null]);throw new LogicException('expected error');}catch(RuntimeException $e){check($e->getMessage()==='Analytics provider HTTP 429','quota errors sanitized');}$transport->status=200;
