    $d=$t->get();$next=array_replace($d,['enabled'=>true,'hosts'=>['site.example'],'matomo_id'=>'42','matomo_url'=>$mc['endpoint'],'plausible_id'=>'site.example','plausible_url'=>$pc['endpoint']]);reject(fn()=>$t->update($next),InvalidArgumentException::class,'custom script origin requires operator permission');putenv('CONSENT_SCRIPT_ORIGINS=https://stats.example.com');$next=$t->update($next);check(in_array('https://stats.example.com',TrackingConfig::csp($next)['script'],true)&&in_array('https://plausible.io',TrackingConfig::csp($next)['connect'],true),'approved tracking CSP');check((new ConsentPolicy($work))->publicConfig()['tracking']===$next,'public config includes trackers without tokens');reject(fn()=>$t->update(array_replace($next,['gtm_id'=>'GTM-ABCDE'])),InvalidArgumentException::class,'GTM remains exclusive');
    $e=new EventConfig($work);$rules=$e->get();$rules['collect_diagnostics']=true;$rules['rules'][1]['matomo']='';$e->update($rules);$policy=(new ConsentPolicy($work))->publicConfig();$journal=new EventJournal($work);check($journal->collect(['id'=>str_repeat('a',32),'name'=>'search','version'=>$policy['version'],'outcomes'=>['plausible'=>'submitted']],'site.example')['accepted'],'Plausible diagnostic accepted');reject(fn()=>$journal->collect(['id'=>str_repeat('b',32),'name'=>'search','version'=>$policy['version'],'outcomes'=>['matomo'=>'submitted']],'site.example'),InvalidArgumentException::class,'disabled Matomo rule rejected');
    if(!in_array('sqlite',PDO::getAvailableDrivers(),true)){if(in_array('--require-db',$argv,true))throw new RuntimeException('pdo_sqlite required');echo "SKIP SQL + worker regression (pdo_sqlite unavailable)\n";exit(0);}
    $config=new ConfigRepository($work);$config->set('database',['default'=>'sqlite','connections'=>['sqlite'=>['database'=>$work.'/test.sqlite']]]);$db=new DatabaseManager($config);(new MigrationRunner($db->connection(),$root.'/migrations'))->run('sqlite');$q=new FileQueueDriver($work);$vault=new SecretVault('base64:'.base64_encode(random_bytes(32)));$hub=new AnalyticsHub($db,$vault,$q,$config,null,null,null,null,$m,$p);
    $input=['provider'=>'matomo','name'=>'Matomo','resource'=>'42','goal'=>null,'enabled'=>true,'credential'=>$mc];reject(fn()=>$hub->save(null,$input),InvalidArgumentException::class,'unapproved reporting host rejected');$config->set('integrations.allowed_hosts',['stats.example.com','plausible.io']);$a=$hub->save(null,$input);$b=$hub->save(null,array_replace($input,['provider'=>'plausible','resource'=>'site.example','credential'=>$pc,'name'=>'Plausible']));check(!str_contains(json_encode($hub->overview()),'private-'),'credentials absent from overview');
